    /// </summary>
    public const int ResponseCrcOffset = ResponseLengthOffset + 1;

    // OTP slot commands for Management
    /// <summary>
    /// Set device mode/config command.
    /// </summary>
    public const byte CmdDeviceConfig = 0x11;

    /// <summary>
    /// Read device capabilities/config command.
