namespace Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;

/// <summary>
///     The exception that is thrown when an ISO 7816 application has encountered an error.
/// </summary>
/// <remarks>
///     When throwOnError is enabled, the Core exchange API throws for any final status other than 0x9000,
///     including warnings. With it disabled, inspect the returned response's raw status before clearing it.
/// </remarks>
[Serializable]
public class ApduException : Exception
{
    /// <summary>
    ///     Initializes a new instance of the <see cref="ApduException" /> class with a default message.
    /// </summary>
    public ApduException() :
        base("APDU command failed with an unknown error")
    {
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="ApduException" /> class with a specified error
    ///     message.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    public ApduException(string message) :
        base(message)
    {
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="ApduException" /> class with a specified error
    ///     message and a reference to the inner exception that is the cause of this exception.
    /// </summary>
    /// <param name="message">The error message that explains the reason for the exception.</param>
    /// <param name="innerException">
    ///     The exception that is the cause of the current exception,
    ///     or a null reference (<see langword="Nothing" /> in Visual Basic) if no inner exception
    ///     is specified.
    /// </param>
    public ApduException(string message, Exception innerException) :
        base(message, innerException)
    {
    }

    /// <summary>
    ///     Gets or sets the status word (SW), the ISO 7816 numerical value which represents
    ///     the specific error or warning encountered.
    /// </summary>
    /// <value>
    ///     The status word value. This can either be an industry defined error, or vendor defined.
    /// </value>
    public short? SW { get; set; }

    /// <summary>
    ///     Gets or sets the APDU class associated with this exception.
    /// </summary>
    /// <value>
    ///     The class value of the command APDU when the exception occurred.
    /// </value>
    public byte? Cla { get; set; }

    /// <summary>
    ///     Gets or sets the APDU instruction associated with this exception.
    /// </summary>
    /// <value>
    ///     The instruction of the command APDU when the exception occurred.
    /// </value>
    public byte? Ins { get; set; }

    /// <summary>
    ///     Gets or sets the P1 parameter associated with this exception.
    /// </summary>
    /// <value>
    ///     The first parameter of the command APDU when the exception occurred.
    /// </value>
    public byte? P1 { get; set; }

    /// <summary>
    ///     Gets or sets the P2 parameter associated with this exception.
    /// </summary>
    /// <value>
    ///     The second parameter of the command APDU when the exception occurred.
    /// </value>
    public byte? P2 { get; set; }

    /// <summary>
    ///     Creates an <see cref="ApduException" /> from an APDU response with a descriptive error message.
    /// </summary>
    /// <param name="response">The APDU response that indicates an error.</param>
    /// <param name="command">Optional command that produced this response for additional context.</param>
    /// <param name="additionalContext">Optional additional context to include in the error message.</param>
    /// <returns>A new <see cref="ApduException" /> with status word and descriptive message.</returns>
    public static ApduException FromResponse(
        ApduResponse response,
        ApduCommand? command = null,
        string? additionalContext = null)
    {
        var statusMessage = SWConstants.GetStatusMessage(response.SW);
        var message = additionalContext is not null
            ? $"{additionalContext}: {statusMessage} (SW=0x{response.SW:X4})"
            : $"{statusMessage} (SW=0x{response.SW:X4})";

        var exception = new ApduException(message) { SW = response.SW };

        if (command is not { } cmd)
            return exception;

        exception.Cla = cmd.Cla;
        exception.Ins = cmd.Ins;
        exception.P1 = cmd.P1;
        exception.P2 = cmd.P2;

        return exception;
    }

    /// <summary>
    ///     Creates an <see cref="ApduException" /> with a status word and optional context.
    /// </summary>
    /// <param name="sw">The status word.</param>
    /// <param name="additionalContext">Optional additional context to include in the error message.</param>
    /// <returns>A new <see cref="ApduException" /> with status word and descriptive message.</returns>
    public static ApduException FromStatusWord(short sw, string? additionalContext = null)
    {
        var statusMessage = SWConstants.GetStatusMessage(sw);
        var message = additionalContext is not null
            ? $"{additionalContext}: {statusMessage} (SW=0x{sw:X4})"
            : $"{statusMessage} (SW=0x{sw:X4})";

        return new ApduException(message) { SW = sw };
    }
}

