namespace Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;

internal partial class PcscProtocol
{
    internal async Task<PcscProtocolScp> InitializeScpAsync(
        ScpKeyParameters keyParams,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(keyParams);

        var (scpProcessor, encryptor) = await ExchangeGuard.RunAsync(
                exchangeToken =>
                {
                    ThrowIfRecoveryRequired();
                    return ScpInitializer.InitializeScpAsync(
                        GetBaseProcessor(),
                        GetBaseCommandProcessor(),
                        InsSendRemaining,
                        keyParams,
                        exchangeToken,
                        MarkRecoveryRequired);
                },
                cancellationToken)
            .ConfigureAwait(false);

        return new PcscProtocolScp(this, scpProcessor, encryptor);
    }
}

