using System.Security.Cryptography;
using Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;
using Yubico.YubiKit.Core.Utilities;

namespace Yubico.YubiKit.Core.Protocols.SmartCard.Scp;

/// <summary>
///     APDU processor that wraps commands and responses with SCP encryption and MAC.
/// </summary>
internal class ScpProcessor(
    IApduProcessor @delegate,
    ScpState state,
    Action<Exception>? onSecureFailure = null) : IApduProcessor, IDisposable
{
    // SCP Constants
    private const byte ClaBitSecureMessaging = 0x04; // Bit 2 in CLA byte indicates secure messaging
    private const byte InsExternalAuthenticate = 0x82;
    private const int MacLength = 8; // AES-CMAC output truncated to 8 bytes

    private readonly ApduFormatterExtended _apduFormatterExtended = new(SmartCardMaxApduSizes.Yk43);

    /// <summary>
    ///     Gets the SCP state for this processor.
    /// </summary>
    private ScpState State { get; } = state;

    /// <summary>
    ///     Disposes the SCP state, zeroing all session keys.
    /// </summary>
    public void Dispose() => State.Dispose();

    /// <summary>9000, 62xx and 63xx: protected response statuses in SCP03 1.1.2 Public Release, §6.2.5.</summary>
    private static bool IsSuccessOrWarning(short sw) =>
        sw == SWConstants.Success || (sw & 0xFF00) is 0x6200 or 0x6300;

    /// <summary>
    ///     Transmits a command APDU with optional SCP encryption and MAC.
    /// </summary>
    /// <param name="command">The command to transmit.</param>
    /// <param name="useScp">Whether to apply SCP (MAC, encryption, SCP bit). If false, passes through to delegate.</param>
    /// <param name="encrypt">Whether to encrypt the command data (only applies if useScp is true).</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>The response APDU with MAC verified and data decrypted if applicable.</returns>
    public async Task<ApduResponse> TransmitAsync(ApduCommand command, bool useScp, bool encrypt,
        CancellationToken cancellationToken)
    {
        // If SCP is not requested, pass through to delegate directly
        if (!useScp)
            return await @delegate.TransmitAsync(command, false, cancellationToken).ConfigureAwait(false);

        byte[]? scpCommandData = null;
        byte[]? finalCommandData = null;
        byte[]? encryptedData = null; // Retain the encrypted copy for finally cleanup on every exit.
        Memory<byte> formattedApdu = default;

        // Record completed Encrypt/Mac calls so subsequent failures notify the recovery owner. Encrypt
        // increments its counter before AES can fail, whereas this flag is set only after it returns;
        // an exception inside Encrypt can therefore escape this notification boundary. This flag alone
        // is not proof that host/card state remains synchronized after every provider failure.
        var stateAdvanced = false;

        try
        {
            // Step 1: Encrypt command data if requested
            // Current code pads and encrypts empty input too. SCP03 1.1.2 Public Release §6.2.6 instead
            // requires the off-card entity to advance the counter without encrypting an absent data field.
            // Preserve that implementation/profile discrepancy separately from counter synchronization.
            var commandData = command.Data;
            if (encrypt)
            {
                encryptedData = State.Encrypt(commandData.Span);
                stateAdvanced = true;
                commandData = encryptedData;
            }

            // Step 2: Ensure CLA has SM bit set (bit 2)
            var cla = (byte)(command.Cla | ClaBitSecureMessaging);

            // Step 3: Allocate buffer for data + MAC (matching Java approach)
            using var macedData = new DisposableArrayPoolBuffer(commandData.Length + MacLength);
            commandData.Span.CopyTo(macedData.Span);

            // Step 4: Create command with FULL length (data + MAC space)
            // This ensures Lc in formatted APDU = data.length + 8
            scpCommandData = macedData.Span.ToArray();
            var scpCommand = new ApduCommand(cla, command.Ins, command.P1, command.P2, scpCommandData, command.Le);

            // Step 5: Format the APDU with full length
            bool isExtendedApdu;
            if (macedData.Length > SmartCardMaxApduSizes.ShortApduMaxChunkSize)
            {
                formattedApdu = _apduFormatterExtended.Format(scpCommand);
                isExtendedApdu = true;
            }
            else
            {
                formattedApdu = Formatter.Format(scpCommand);
                isExtendedApdu = Formatter is ApduFormatterExtended;
            }

            // Step 6: Compute MAC over formatted APDU minus the MAC placeholder and trailing Le.
            var apduToMac = formattedApdu.Span;
            // SCP commands always include the data field because macedData reserves the 8-byte MAC slot,
            // so extended APDUs use the data-bearing 2-byte Le form rather than no-data Case 2E.
            var leLength = isExtendedApdu ? 2 : 1;
            var macLength = apduToMac.Length - MacLength - leLength;

            // Step 7: Compute the MAC straight into the reserved slot in the last 8 bytes
            State.Mac(apduToMac[..macLength], macedData.Span[commandData.Length..]);
            stateAdvanced = true;

            // Step 8: Create final command with MAC filled in
            finalCommandData = macedData.Span.ToArray();
            var finalCommand = new ApduCommand(cla, command.Ins, command.P1, command.P2, finalCommandData, command.Le);

            // The command is already wrapped; the secure transmitter detects rejected
            // intermediate chunks before they can masquerade as terminal responses.
            var response = await @delegate.TransmitAsync(finalCommand, false, cancellationToken).ConfigureAwait(false);

            // Step 10: Verify and remove MAC from response
            if (response.Data.Length > 0)
            {
                var unmacdData = State.Unmac(response.Data.Span, response.SW);

                // Step 11: Decrypt response data
                // This processor decrypts nonempty un-MACed response data, independently of command
                // encryption. The decrypted temporary and the response's cloned owner are separate copies.
                if (unmacdData.Length > 0)
                {
                    try
                    {
                        return new ApduResponse(State.Decrypt(unmacdData), response.SW);
                    }
                    finally
                    {
                        CryptographicOperations.ZeroMemory(unmacdData);
                    }
                }

                return new ApduResponse(unmacdData, response.SW);
            }

            // SCP03 1.1.2 Public Release §6.2.5 requires card R-MAC for 9000/62xx/63xx, except the
            // EXTERNAL AUTHENTICATE response, and status-only unprotected errors otherwise. The check
            // below identifies the exception by INS 82 alone, not by handshake phase; later raw INS 82
            // calls also reach it. Missing-R-MAC rejection is not universal phase-gating evidence.
            if (IsSuccessOrWarning(response.SW) && command.Ins != InsExternalAuthenticate)
            {
                throw new BadResponseException(
                    $"Response with status 0x{response.SW:X4} carries no R-MAC; every success under SCP is authenticated.");
            }

            return response;
        }
        // After a completed Encrypt/Mac call, report the original failure (including cancellation) so
        // the owner refuses further exchanges. Rethrow unchanged and without replay. Earlier internal
        // counter mutation can precede this flag; see its declaration above.
        catch (Exception ex) when (stateAdvanced)
        {
            onSecureFailure?.Invoke(ex);
            throw;
        }
        finally
        {
            CryptographicOperations.ZeroMemory(encryptedData.AsSpan());
            CryptographicOperations.ZeroMemory(formattedApdu.Span);
            CryptographicOperations.ZeroMemory(scpCommandData.AsSpan());
            CryptographicOperations.ZeroMemory(finalCommandData.AsSpan());
        }
    }


    /// <summary>
    ///     Gets the APDU formatter.
    /// </summary>
    public IApduFormatter Formatter { get; } = @delegate.Formatter;

    /// <summary>
    ///     Transmits a command APDU with SCP encryption and MAC, and processes the response.
    /// </summary>
    public Task<ApduResponse> TransmitAsync(ApduCommand command, bool useScp = true,
        CancellationToken cancellationToken = default)
        => TransmitAsync(command, useScp, true, cancellationToken);

}

