using Microsoft.Extensions.Logging;
using Yubico.YubiKit.Core.Abstractions;
using Yubico.YubiKit.Core.Credentials;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Core.Protocols;
using Yubico.YubiKit.Core.Protocols.Fido.Hid;
using Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;
using Yubico.YubiKit.Core.Protocols.SmartCard.Scp;

namespace Yubico.YubiKit.Core.Sessions;

/// <summary>
///     Base class for applet and raw sessions that attach to one opened YubiKey connection.
/// </summary>
/// <remarks>
///     <para>
///         One connection admits one live session. A direct session factory borrows its caller's connection;
///         only an <c>IYubiKey.Create*SessionAsync</c> convenience entry point can transfer ownership of a
///         hidden connection to the returned session.
///     </para>
///     <para>
///         Protocol construction and initialization are internal SDK seams. External derived classes cannot
///         inject or replace Core protocol implementations; compose over a public raw session for low-level work.
///     </para>
///     <para>
///         Protocol guards admit individual logical exchanges, not an entire multi-exchange applet workflow.
///         Await each complete public operation, including parsing and callbacks, before disposing the session
///         or starting a competing workflow. Disposal drains the admitted exchange, not every public task or
///         detached callback task. Keep disposal outside the operation and its user-presence callbacks.
///     </para>
/// </remarks>
public abstract class ApplicationSession : IApplicationSession, IAsyncDisposable
{
    private readonly DisposalGate _disposalGate = new();
    // Guards reject calls that begin after disposal starts. Operations already in flight have no lifetime
    // admission lease and may complete, fail at a later guard, or race teardown.
    private int _disposalStarted;
    private bool _isInitialized;
    private bool _isAuthenticated;
    private bool _disposed;
    private int _released;
    private bool _ownsConnection;
    private readonly IUserPresencePrompt? _userPresencePrompt;

    protected ILogger Logger { get; }
    internal IProtocol? Protocol { get; set; }
    protected bool IsDisposalStarted => Volatile.Read(ref _disposalStarted) != 0;

    /// <summary>
    ///     The connection this session runs over. Unless an <c>IYubiKey.Create*SessionAsync</c> entry point
    ///     transferred ownership, the session borrows it: disposing the session detaches the session but never
    ///     disposes a caller-created connection.
    /// </summary>
    /// <remarks>
    ///     After healthy idle or sequential use, the borrowed connection can host the next session. Detaching
    ///     is ownership bookkeeping, not proof that connection or device state is reusable. A failed partial
    ///     exchange, a failed OTP reset, or disposal that begins while a FIDO HID exchange is active on the
    ///     built-in macOS connection can leave the connection unusable; the terminal wake used for that disposal
    ///     may do so even when the exchange finishes concurrently with it. After such uncertainty, dispose and
    ///     reopen the connection. Disposal does not always end the connection: a SmartCard disposal drains an
    ///     admitted exchange, and a successful drained exchange leaves the borrowed connection reusable.
    /// </remarks>
    protected IConnection Connection { get; }

    public FirmwareVersion FirmwareVersion { get; protected set; } = new();
    public ConnectionType ConnectionType => Connection.Type;

    public bool IsInitialized
    {
        get => Volatile.Read(ref _disposalStarted) == 0 && _isInitialized;
        protected set => _isInitialized = value;
    }

    public bool IsAuthenticated
    {
        get => Volatile.Read(ref _disposalStarted) == 0 && _isAuthenticated;
        protected set => _isAuthenticated = value;
    }

    /// <summary>
    ///     Records the connection this session will run over. Does NOT bind the session to it — see
    ///     <see cref="Construct{TSession}" />, which binds once construction has actually succeeded.
    /// </summary>
    /// <param name="connection">The connection the session will run over.</param>
    protected ApplicationSession(IConnection connection)
        : this(connection, userPresencePrompt: null)
    {
    }

    /// <summary>
    ///     Records the connection and caller-owned user-presence notification service this session will use.
    /// </summary>
    /// <param name="connection">The connection the session will run over.</param>
    /// <param name="userPresencePrompt">
    ///     The optional notification service to retain for the session lifetime. The session does not dispose it.
    /// </param>
    protected ApplicationSession(IConnection connection, IUserPresencePrompt? userPresencePrompt)
    {
        ArgumentNullException.ThrowIfNull(connection);

        Logger = YubiKitLogging.CreateLogger(GetType().FullName ?? GetType().Name);
        Connection = connection;
        _userPresencePrompt = userPresencePrompt;
    }

    /// <summary>Gets whether this session retained a user-presence prompt.</summary>
    internal bool IsUserPresenceNotificationEnabled => _userPresencePrompt is not null;

    /// <summary>Creates the non-null notification handle for one operation.</summary>
    /// <param name="context">The optional policy context determined by the applet session.</param>
    /// <returns>An enabled per-operation handle, or the shared no-op handle.</returns>
    internal UserPresenceNotification CreateUserPresenceNotification(UserPresenceContext? context) =>
        UserPresenceNotification.Create(_userPresencePrompt, context);

    /// <summary>Runs an ordinary operation with request, outcome mapping, and terminal resolution.</summary>
    /// <typeparam name="TResult">
    ///     The operation result type. An operation that creates caller-owned sensitive data or immutable secret
    ///     material must resolve <paramref name="notification" /> before transferring or materializing that result,
    ///     and must clear any owned intermediate data if resolution fails.
    /// </typeparam>
    /// <param name="notification">The non-null per-operation notification handle.</param>
    /// <param name="operation">The operation to run after the request callback succeeds.</param>
    /// <param name="cancellationToken">The operation cancellation token.</param>
    /// <returns>The operation result.</returns>
    internal async Task<TResult> RunWithUserPresenceNotificationAsync<TResult>(
        UserPresenceNotification notification,
        Func<CancellationToken, Task<TResult>> operation,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(notification);
        ArgumentNullException.ThrowIfNull(operation);

        return await RunWithUserPresenceResolutionAsync(
                notification,
                async token =>
                {
                    await notification.RequestAsync(token).ConfigureAwait(false);
                    return await operation(token).ConfigureAwait(false);
                },
                cancellationToken)
            .ConfigureAwait(false);
    }

    /// <summary>
    ///     Runs an operation that owns request timing while this method owns outcome mapping and terminal resolution.
    /// </summary>
    /// <typeparam name="TResult">
    ///     The operation result type. An operation that creates caller-owned sensitive data or immutable secret
    ///     material must resolve <paramref name="notification" /> before transferring or materializing that result,
    ///     and must clear any owned intermediate data if resolution fails.
    /// </typeparam>
    /// <param name="notification">The non-null per-operation notification handle.</param>
    /// <param name="operation">The operation that may request at its transport boundary.</param>
    /// <param name="cancellationToken">The operation cancellation token.</param>
    /// <returns>The operation result.</returns>
    /// <remarks>
    ///     This method provides fallback resolution for failure and cancellation paths. It cannot reclaim a result
    ///     already produced by <paramref name="operation" /> if the terminal callback then fails, so the result's
    ///     producing owner must explicitly resolve successful sensitive operations before ownership transfer.
    /// </remarks>
    internal async Task<TResult> RunWithUserPresenceResolutionAsync<TResult>(
        UserPresenceNotification notification,
        Func<CancellationToken, Task<TResult>> operation,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(notification);
        ArgumentNullException.ThrowIfNull(operation);

        var outcome = UserPresenceOutcome.Failed;
        Exception? primaryException = null;
        try
        {
            TResult result = await operation(cancellationToken).ConfigureAwait(false);
            outcome = UserPresenceOutcome.Completed;
            return result;
        }
        catch (OperationCanceledException ex) when (cancellationToken.IsCancellationRequested)
        {
            outcome = UserPresenceOutcome.Cancelled;
            primaryException = ex;
            throw;
        }
        catch (Exception ex)
        {
            primaryException = ex;
            throw;
        }
        finally
        {
            await notification.ResolveAsync(outcome, primaryException).ConfigureAwait(false);
        }
    }

    /// <summary>
    ///     Constructs a session and binds it to its connection, enforcing one live session per connection.
    /// </summary>
    /// <remarks>
    ///     <para>
    ///         Binding deliberately happens here rather than in the constructor. A constructor that binds and
    ///         then throws leaves nothing to unbind it: the object never finishes construction, so no
    ///         <c>using</c>, <c>finally</c> or factory <c>catch</c> can reach it, and the connection is
    ///         refused forever by a session that does not exist. Binding after <paramref name="create" />
    ///         returns makes that state unrepresentable.
    ///     </para>
    ///     <para>
    ///         It must NOT move later still — into initialization — because derived
    ///         <c>InitializeAsync</c> implementations issue their applet SELECT before calling
    ///         <see cref="ConfigureProtocolAsync" />. Binding there would refuse the second session only after
    ///         the first session's state had already been destroyed, which is the damage this guard exists to
    ///         prevent. Construction performs no wire I/O, so here is the last safe point.
    ///     </para>
    ///     <para>
    ///         On refusal the constructed session is disposed and the exception propagates. Disposal cannot
    ///         disturb the incumbent: <see cref="ConnectionSessionGuard.Detach" /> only clears the slot when
    ///         the disposing session is the recorded holder, and this one never became it.
    ///     </para>
    /// </remarks>
    /// <exception cref="ConnectionInUseException">The connection already has a live session.</exception>
    protected static TSession Construct<TSession>(IConnection connection, Func<TSession> create)
        where TSession : ApplicationSession
    {
        ArgumentNullException.ThrowIfNull(connection);
        ArgumentNullException.ThrowIfNull(create);

        var session = create();
        try
        {
            ConnectionSessionGuard.Attach(connection, session);
        }
        catch
        {
            session.Dispose();
            throw;
        }

        return session;
    }

    private protected static async Task<TSession> ConstructInitializedAsync<TSession>(
        IConnection connection,
        SessionCreationOptions? options,
        Func<TSession> create,
        Func<TSession, CancellationToken, Task> initialize,
        CancellationToken cancellationToken)
        where TSession : ApplicationSession
    {
        ArgumentNullException.ThrowIfNull(initialize);
        ValidatePreferredConnectionType(connection, options);

        var session = Construct(connection, create);
        try
        {
            await session.InitializeSessionAsync(token => initialize(session, token), cancellationToken)
                .ConfigureAwait(false);
            return session;
        }
        catch
        {
            session.DisposeAfterInitializationFailure();
            throw;
        }
    }

    /// <summary>
    ///     Validates the connection-type assertion supplied to a direct session factory.
    /// </summary>
    /// <param name="connection">The caller-owned connection.</param>
    /// <param name="options">Optional session creation settings.</param>
    /// <exception cref="ArgumentException">
    ///     <see cref="SessionCreationOptions.PreferredConnectionType" /> does not match the connection.
    /// </exception>
    private protected static void ValidatePreferredConnectionType(
        IConnection connection,
        SessionCreationOptions? options)
    {
        ArgumentNullException.ThrowIfNull(connection);

        if (options?.PreferredConnectionType is { } preferredConnectionType &&
            preferredConnectionType != connection.Type)
        {
            throw new ArgumentException(
                $"The provided connection is {connection.Type}, not the requested {preferredConnectionType}.",
                nameof(options));
        }
    }

    /// <summary>
    ///     Transfers ownership of <see cref="Connection" /> to this session, so disposing the session also
    ///     disposes the connection.
    /// </summary>
    /// <remarks>
    ///     Only the code that CREATED the connection may call this, and only the convenience
    ///     <c>IYubiKey.Create&lt;App&gt;SessionAsync</c> entry points do: they open a connection the caller
    ///     never sees, so the session they return is the only thing that can close it. A caller who opened the
    ///     connection keeps ownership and this is never called.
    /// </remarks>
    internal void OwnConnection() => _ownsConnection = true;

    internal async Task InitializeSessionAsync(
        Func<CancellationToken, Task> initialize,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(initialize);
        ThrowIfDisposed();
        EnsureConnectionBound();

        if (IsInitialized)
            return;

        await initialize(cancellationToken).ConfigureAwait(false);
        ThrowIfDisposed();
        IsInitialized = true;
    }

    internal async Task<IProtocol> PrepareProtocolAsync(
        ScpKeyParameters? scpKeyParams,
        CancellationToken cancellationToken)
    {
        ThrowIfDisposed();
        EnsureConnectionBound();
        cancellationToken.ThrowIfCancellationRequested();

        var protocol = ProtocolFactory.Create(Connection);
        Protocol = protocol;
        _ = GetScpProtocol(protocol, scpKeyParams);

        if (protocol is IFidoHidProtocol fidoProtocol)
            await fidoProtocol.InitializeAsync(cancellationToken).ConfigureAwait(false);

        return protocol;
    }

    private static PcscProtocol? GetScpProtocol(IProtocol protocol, ScpKeyParameters? scpKeyParams) =>
        (protocol, scpKeyParams) switch
        {
            (PcscProtocol pcscProtocol, not null) => pcscProtocol,
            (not PcscProtocol, not null) => throw new NotSupportedException(
                "SCP is only supported on PC/SC SmartCard protocols created by Core."),
            (_, null) => null
        };

    private void EnsureConnectionBound()
    {
        if (!ConnectionSessionGuard.IsHolder(Connection, this))
            throw new InvalidOperationException(
                $"{GetType().Name} was not bound to its connection. Sessions must be created through their " +
                "CreateAsync factory, which routes construction through ApplicationSession.Construct so the " +
                "one-live-session-per-connection rule is enforced before any wire operation.");
    }

    internal async Task<IProtocol> ConfigureProtocolAsync(
        IProtocol protocol,
        FirmwareVersion firmwareVersion,
        ProtocolConfiguration? configuration = null,
        ScpKeyParameters? scpKeyParams = null,
        CancellationToken cancellationToken = default)
    {
        // Checked before the IsInitialized early-return: a derived session that sets IsInitialized
        // itself would otherwise skip the bind check entirely and run unguarded.
        // Binding is not automatic, so a session reaching initialization without having gone through
        // Construct could run concurrently with another on the same connection and deselect its applet.
        EnsureConnectionBound();

        ArgumentNullException.ThrowIfNull(protocol);

        if (IsInitialized)
            return Protocol ?? protocol;

        protocol.Configure(firmwareVersion, configuration);

        IProtocol effectiveProtocol = protocol;
        var isAuthenticated = false;

        if (GetScpProtocol(protocol, scpKeyParams) is { } pcscProtocol && scpKeyParams is not null)
        {
            effectiveProtocol = await pcscProtocol
                .InitializeScpAsync(scpKeyParams, cancellationToken)
                .ConfigureAwait(false);

            isAuthenticated = true;
        }

        // Only mutate session state on successful completion.
        Protocol = effectiveProtocol;
        FirmwareVersion = firmwareVersion;
        IsAuthenticated = isAuthenticated;

        return effectiveProtocol;
    }

    /// <summary>
    ///     Releases resources owned by a session whose asynchronous factory failed. Disposal failures
    ///     are logged and suppressed so the initialization exception remains the primary failure.
    /// </summary>
    protected void DisposeAfterInitializationFailure()
    {
        try
        {
            Dispose();
        }
        catch (Exception ex)
        {
            try
            {
                Logger.LogWarning(ex, "Failed to dispose session resources after initialization failed");
            }
            catch
            {
                // Initialization is already failing. Logging must not replace that original exception.
            }
        }
    }

    /// <summary>Evaluates known firmware compatibility without guaranteeing runtime operation success.</summary>
    /// <remarks>Authentication, device configuration, and actual command support are checked by operations.</remarks>
    public bool IsSupported(Feature feature) =>
        feature.IsSupportedByFirmware(FirmwareVersion);

    /// <summary>Enforces a firmware prerequisite within a derived session operation.</summary>
    protected void EnsureSupports(Feature feature)
    {
        if (!IsSupported(feature))
            throw new NotSupportedException($"{feature.Name} requires firmware {feature.Version}+");
    }

    protected void ThrowIfDisposed()
    {
        ObjectDisposedException.ThrowIf(Volatile.Read(ref _disposalStarted) != 0, this);
    }

    /// <summary>Closes session admission, drains an admitted protocol exchange, and releases session resources.</summary>
    /// <remarks>
    ///     This synchronous path blocks while an admitted exchange finishes. Prefer <see cref="DisposeAsync" />
    ///     for asynchronous callers. Invoke either disposal path outside the operation and its callbacks;
    ///     awaiting asynchronous disposal from a callback can also wait on its own exchange.
    /// </remarks>
    public void Dispose()
    {
        BeginDisposal();
        _disposalGate.Dispose(() => Dispose(disposing: true));
        GC.SuppressFinalize(this);
    }

    /// <summary>
    ///     Closes session admission, asynchronously drains an admitted protocol exchange, and releases session resources.
    /// </summary>
    /// <remarks>Await complete public workflows first; the drain covers the exchange rather than the whole workflow.</remarks>
    public async ValueTask DisposeAsync()
    {
        BeginDisposal();
        await _disposalGate.DisposeAsync(DisposeSessionAsync).ConfigureAwait(false);
        GC.SuppressFinalize(this);
    }

    private void BeginDisposal()
    {
        Interlocked.Exchange(ref _disposalStarted, 1);
        // Clear the backing state as a teardown backstop. The public getters also observe
        // _disposalStarted, so their result becomes false at the admission boundary.
        IsAuthenticated = false;
        IsInitialized = false;
    }

    private async ValueTask DisposeSessionAsync()
    {
        try
        {
            await DisposeAsyncCore().ConfigureAwait(false);
        }
        finally
        {
            // Managed state and sensitive buffers must be cleared even if asynchronous connection teardown fails.
            Dispose(disposing: true);
        }
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_disposed)
            return;

        // A disposed session has no usable protocol or authenticated channel, even when teardown fails.
        IsAuthenticated = false;
        IsInitialized = false;

        try
        {
            try
            {
                if (disposing)
                    DisposeProtocol();
            }
            finally
            {
                // Protocol failure must not retain the session guard or an owned connection.
                ReleaseConnection();
            }
        }
        finally
        {
            // A failed teardown is still terminal; DisposalGate shares that failed completion with every caller.
            _disposed = true;
        }
    }

    protected virtual async ValueTask DisposeAsyncCore()
    {
        try
        {
            await DisposeProtocolAsync().ConfigureAwait(false);
        }
        finally
        {
            await ReleaseConnectionAsync().ConfigureAwait(false);
        }
    }

    private void DisposeProtocol()
    {
        IProtocol? protocol = Protocol;
        Protocol = null;
        protocol?.Dispose();
    }

    private async ValueTask DisposeProtocolAsync()
    {
        IProtocol? protocol = Protocol;
        Protocol = null;
        if (protocol is IAsyncDisposable asyncDisposable)
            await asyncDisposable.DisposeAsync().ConfigureAwait(false);
        else
            protocol?.Dispose();
    }

    /// <summary>Detaches from the connection, and disposes it only if this session was given ownership.</summary>
    private void ReleaseConnection()
    {
        if (!TryClaimRelease())
            return;

        if (_ownsConnection)
            Connection.Dispose();
    }

    /// <inheritdoc cref="ReleaseConnection" />
    private async ValueTask ReleaseConnectionAsync()
    {
        if (!TryClaimRelease())
            return;

        if (_ownsConnection)
            await Connection.DisposeAsync().ConfigureAwait(false);
    }

    private bool TryClaimRelease()
    {
        if (Interlocked.Exchange(ref _released, 1) != 0)
            return false;

        ConnectionSessionGuard.Detach(Connection, this);
        return true;
    }
}

