    /// <summary>
    /// Checks one CANCEL, original-response drain, and a subsequent scripted exchange after cancellation
    /// during keep-alive. The vendor-command script is a managed lifetime oracle, not normative CBOR
    /// cancellation behavior or evidence that a physical key requires re-plugging.
    /// </summary>
    /// <remarks>
    /// The caller is abandoned mid-exchange rather than up front: <see cref="ExchangeGuard"/>
    /// rejects an already-cancelled token before the exchange is admitted, so a pre-cancelled
    /// token would never reach the keep-alive loop this covers.
    /// </remarks>
    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    [Trait("Category", "RuntimeResilience")]
    public async Task SendCommandAsync_AbandonedDuringKeepAlive_SendsExactlyOneCancelAndLeavesChannelUsable(
        int keepAliveCount)
    {
        var connection = new FakeFidoHidConnection();
        var protocol = new FidoHidProtocol(connection);
        var prompt = new RecordingUserPresencePrompt();
        var context = CreateUserPresenceContext();
        using var cts = new CancellationTokenSource();

        // The script reports a touch wait, then terminates the original vendor command with byte 0x2D.
        // CTAPHID CANCEL itself has no response; normative KEEPALIVE_CANCEL belongs to a CBOR response.
        connection.QueueResponsePackets([
            .. Enumerable.Range(0, keepAliveCount).Select(_ =>
                CreateInitPacket(TestChannelId, CtapConstants.CtapHidKeepAlive, [KeepAliveUpNeeded])),
            CreateInitPacket(TestChannelId, CtapConstants.CtapVendorFirst, [0x2D])
        ]);

        // Abandon the moment the authenticator says it is waiting for a touch.
        connection.OnResponseDequeued = packet =>
        {
            if (IsCommand(packet, CtapConstants.CtapHidKeepAlive))
                cts.Cancel();
        };

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            protocol.SendCommandAsync(
                CtapConstants.CtapVendorFirst,
                ReadOnlyMemory<byte>.Empty,
                UserPresenceNotification.Create(prompt, context),
                cts.Token));

        Assert.Equal(
            1,
            connection.SentPacketSnapshots.Count(packet => IsCommand(packet, CtapConstants.CtapHidCancel)));
        Assert.Single(prompt.Requested);
        Assert.Empty(prompt.Resolved);

        // A later scripted response checks that the original response was consumed before reuse.
        connection.OnResponseDequeued = null;
        connection.QueueResponsePackets(
            CreateInitPacket(TestChannelId, CtapConstants.CtapVendorFirst, [0xAA]));

        var afterCancel = await protocol.SendCommandAsync(
            CtapConstants.CtapVendorFirst,
            ReadOnlyMemory<byte>.Empty,
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(0xAA, afterCancel.Span[0]);
    }

