using Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;

namespace Yubico.YubiKit.Core.UnitTests.Protocols.SmartCard.Apdu.Fakes;

/// <summary>
///     Fake implementation of IApduProcessor for unit testing.
/// </summary>
internal sealed class FakeApduProcessor : IApduProcessor
{
    private readonly Queue<Func<ApduResponse>> _responses = new();
    public List<ApduCommand> TransmittedCommands { get; } = [];


    public IApduFormatter Formatter { get; set; } = new FakeApduFormatter();

    public async Task<ApduResponse> TransmitAsync(
        ApduCommand command,
        bool useScp = true,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();

        TransmittedCommands.Add(command);

        if (_responses.Count == 0)
            throw new InvalidOperationException("No response enqueued for transmission");

        return await Task.FromResult(_responses.Dequeue()());
    }


    public void EnqueueResponse(ApduResponse response) => _responses.Enqueue(() => response);

    /// <summary>Builds the response when the command arrives, for replies that depend on state advanced by sending it.</summary>
    public void EnqueueResponse(Func<ApduResponse> response) => _responses.Enqueue(response);

    public void EnqueueResponse(byte sw1, byte sw2, ReadOnlyMemory<byte> data = default)
    {
        var responseBytes = new byte[data.Length + 2];
        data.Span.CopyTo(responseBytes);
        responseBytes[^2] = sw1;
        responseBytes[^1] = sw2;
        var response = new ApduResponse(responseBytes);
        _responses.Enqueue(() => response);
    }
}

/// <summary>
///     Fake implementation of IApduFormatter for testing.
/// </summary>
internal class FakeApduFormatter : IApduFormatter
{

    public Memory<byte> Format(byte cla, byte ins, byte p1, byte p2, ReadOnlyMemory<byte> data, int le)
    {
        var buffer = new List<byte> { cla, ins, p1, p2 };

        if (data.Length > 0)
        {
            buffer.Add((byte)data.Length);
            buffer.AddRange(data.ToArray());
        }

        if (le > 0)
            buffer.Add((byte)le);

        return buffer.ToArray();
    }

    public Memory<byte> Format(ApduCommand apdu) =>
        Format(apdu.Cla, apdu.Ins, apdu.P1, apdu.P2, apdu.Data, apdu.Le);

}

