            0xe9, 0x3d, 0x7e, 0x11, 0x73, 0x93, 0x17
        ];

        using var cmac = new AesCmac(TestKey);
        cmac.AppendData(message);
        var mac = cmac.GetHashAndReset();

        // MAC should be 16 bytes
